int attach_usb_serial_for_treo_kyocera(struct usb_serial *serial) {
    struct usb_endpoint_descriptor *ep_in, *ep_out;
    int i, num_interrupt, num_bulk_in;
    struct usb_serial_endpoint *temp_port;

    if (serial->dev->descriptor.idVendor != 0x04e8 && serial->dev->descriptor.idVendor != 0x04a9) {
        return 0; // Not a Handspring or Kyocera device
    }

    num_interrupt = 0;
    num_bulk_in = 0;

    for (i = 0; i < serial->interface->num_altsetting; i++) {
        ep_in = serial->interface->altsetting[i].endpoint;
        for (int j = 0; j < serial->interface->altsetting[i].desc.bNumEndpoints; j++) {
            if (ep_in[j].bmAttributes & USB_ENDPOINT_XFER_INT)
                num_interrupt++;
            if (ep_in[j].bmAttributes & USB_ENDPOINT_XFER_BULK)
                num_bulk_in++;
        }
    }

    if (num_interrupt < 2 || num_bulk_in < 2) {
        dev_err(&serial->dev->dev, "Missing required endpoints for Treo/Kyocera device\n");
        return -ENODEV;
    }

    // Swap the first and second bulk in and interrupt endpoints
    temp_port = kmalloc(sizeof(struct usb_serial_endpoint), GFP_KERNEL);
    if (!temp_port)
        return -ENOMEM;

    memcpy(temp_port, &serial->bulk_in[0], sizeof(struct usb_serial_endpoint));
    memcpy(&serial->bulk_in[0], &serial->bulk_in[1], sizeof(struct usb_serial_endpoint));
    memcpy(&serial->bulk_in[1], temp_port, sizeof(struct usb_serial_endpoint));

    memcpy(temp_port, &serial->interrupt_in[0], sizeof(struct usb_serial_endpoint));
    memcpy(&serial->interrupt_in[0], &serial->interrupt_in[1], sizeof(struct usb_serial_endpoint));
    memcpy(&serial->interrupt_in[1], temp_port, sizeof(struct usb_serial_endpoint));

    kfree(temp_port);
    return 0;
}

