int attach_usb_serial_handheld(struct usb_serial *serial)
{
    struct usb_host_endpoint **in_eps;
    struct usb_host_endpoint **int_in_eps;
    int i;

    in_eps = serial->interface->cur_altsetting->endpoint;
    int_in_eps = serial->interface->cur_altsetting->endpoint;

    for (i = 0; i < serial->interface->num_altsetting; ++i) {
        struct usb_host_endpoint **eps = serial->interface->altsetting[i].endpoint;
        int j;
        int has_bulk_in = 0;
        int has_int_in = 0;

        for (j = 0; j < serial->interface->altsetting[i].desc.bNumEndpoints; ++j) {
            if (eps[j]->desc.bmAttributes & USB_ENDPOINT_XFER_BULK) {
                if (eps[j]->desc.bEndpointAddress & USB_DIR_IN)
                    has_bulk_in++;
            } else if (eps[j]->desc.bmAttributes & USB_ENDPOINT_XFER_INT) {
                if (eps[j]->desc.bEndpointAddress & USB_DIR_IN)
                    has_int_in++;
            }
        }

        if (has_bulk_in >= 2 && has_int_in >= 2)
            break;
    }

    if (i >= serial->interface->num_altsetting) {
        dev_dbg(&serial->dev, "No suitable altsetting found for Handspring/Treo/Kyocera\n");
        return -ENODEV;
    }

    serial->interface->altsetting = &serial->interface->altsetting[i];
    serial->interface->num_altsetting = 1;
    serial->interface->cur_altsetting = serial->interface->altsetting;

    in_eps = serial->interface->cur_altsetting->endpoint;
    int_in_eps = serial->interface->cur_altsetting->endpoint;

    for (i = 0; i < serial->interface->cur_altsetting->desc.bNumEndpoints; ++i) {
        if (in_eps[i]->desc.bmAttributes == USB_ENDPOINT_XFER_BULK &&
            in_eps[i]->desc.bEndpointAddress & USB_DIR_IN) {
            if (serial->bulk_in_size < 2)
                serial->bulk_in_size = 2;

            serial->bulk_in[0] = serial->bulk_in[1];
            serial->bulk_in[1] = in_eps[i];
            break;
        }
    }

    for (; i < serial->interface->cur_altsetting->desc.bNumEndpoints; ++i) {
        if (int_in_eps[i]->desc.bmAttributes == USB_ENDPOINT_XFER_INT &&
            int_in_eps[i]->desc.bEndpointAddress & USB_DIR_IN) {
            if (serial->interrupt_in_size < 2)
                serial->interrupt_in_size = 2;

            serial->interrupt_in[0] = serial->interrupt_in[1];
            serial->interrupt_in[1] = int_in_eps[i];
            break;
        }
    }

    serial->num_ports = 1;
    serial->port[0] = kzalloc(sizeof(*serial->port[0]), GFP_KERNEL);
    if (!serial->port[0])
        return -ENOMEM;

    serial->port[0]->serial = serial;
    serial->port[0]->port = 0;

    return 0;
}

